export class TextDocument {
  constructor(uri, languageId, version, content) {
    this.uri = uri;
    this.languageId = languageId;
    this.version = version;
    this._content = content;
    this._lineOffsets = undefined;
  }

  static create(uri, languageId, version, content) {
    return new TextDocument(uri, languageId, version, content);
  }

  get lineCount() {
    return this._computeLineOffsets().length;
  }

  getText(range) {
    if (!range) {
      return this._content;
    }
    const start = this.offsetAt(range.start);
    const end = this.offsetAt(range.end);
    return this._content.slice(start, end);
  }

  offsetAt(position) {
    const lineOffsets = this._computeLineOffsets();
    if (position.line >= lineOffsets.length) {
      return this._content.length;
    }
    if (position.line < 0) {
      return 0;
    }
    const lineOffset = lineOffsets[position.line];
    const nextLineOffset =
      position.line + 1 < lineOffsets.length ? lineOffsets[position.line + 1] : this._content.length;
    return Math.max(Math.min(lineOffset + position.character, nextLineOffset), lineOffset);
  }

  positionAt(offset) {
    const clamped = Math.max(Math.min(offset, this._content.length), 0);
    const lineOffsets = this._computeLineOffsets();
    let low = 0;
    let high = lineOffsets.length;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (lineOffsets[mid] > clamped) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }
    const line = Math.max(0, low - 1);
    return { line, character: clamped - lineOffsets[line] };
  }

  update(changes, version) {
    for (const change of changes) {
      if (!change.range) {
        this._content = change.text;
      } else {
        const start = this.offsetAt(change.range.start);
        const end = this.offsetAt(change.range.end);
        this._content = this._content.slice(0, start) + change.text + this._content.slice(end);
      }
    }
    this.version = version;
    this._lineOffsets = undefined;
  }

  _computeLineOffsets() {
    if (this._lineOffsets) {
      return this._lineOffsets;
    }
    const offsets = [0];
    for (let i = 0; i < this._content.length; i++) {
      const ch = this._content.charCodeAt(i);
      if (ch === 13 || ch === 10) {
        if (ch === 13 && i + 1 < this._content.length && this._content.charCodeAt(i + 1) === 10) {
          i++;
        }
        offsets.push(i + 1);
      }
    }
    this._lineOffsets = offsets;
    return offsets;
  }
}

export class TextDocuments {
  constructor(documentFactory = TextDocument) {
    this._documentFactory = documentFactory;
    this._documents = new Map();
    this._emitter = new EventEmitter();
  }

  get(uri) {
    return this._documents.get(uri);
  }

  all() {
    return Array.from(this._documents.values());
  }

  keys() {
    return Array.from(this._documents.keys());
  }

  onDidOpen(listener) {
    this._emitter.on('open', listener);
    return { dispose: () => this._emitter.off('open', listener) };
  }

  onDidChangeContent(listener) {
    this._emitter.on('change', listener);
    return { dispose: () => this._emitter.off('change', listener) };
  }

  onDidClose(listener) {
    this._emitter.on('close', listener);
    return { dispose: () => this._emitter.off('close', listener) };
  }

  onDidSave(listener) {
    this._emitter.on('save', listener);
    return { dispose: () => this._emitter.off('save', listener) };
  }

  listen(connection) {
    connection.onDidOpenTextDocument((params) => {
      const td = params.textDocument;
      const doc = this._documentFactory.create(td.uri, td.languageId, td.version, td.text);
      this._documents.set(td.uri, doc);
      this._emitter.emit('open', { document: doc });
      this._emitter.emit('change', { document: doc });
    });

    connection.onDidChangeTextDocument((params) => {
      const doc = this._documents.get(params.textDocument.uri);
      if (!doc) {
        return;
      }
      if (typeof doc.update === 'function') {
        doc.update(params.contentChanges, params.textDocument.version);
      } else {
        const last = params.contentChanges[params.contentChanges.length - 1];
        if (last) {
          const updated = this._documentFactory.create(
            doc.uri,
            doc.languageId,
            params.textDocument.version,
            last.text,
          );
          this._documents.set(doc.uri, updated);
          this._emitter.emit('change', { document: updated });
          return;
        }
      }
      this._emitter.emit('change', { document: doc });
    });

    connection.onDidSaveTextDocument((params) => {
      const doc = this._documents.get(params.textDocument.uri);
      if (doc) {
        this._emitter.emit('save', { document: doc });
      }
    });

    connection.onDidCloseTextDocument((params) => {
      const doc = this._documents.get(params.textDocument.uri);
      if (doc) {
        this._documents.delete(params.textDocument.uri);
        this._emitter.emit('close', { document: doc });
      }
    });
  }
}

export function createConnection(inputOrFeatures, output) {
  let msgConnection;
  if (inputOrFeatures && typeof inputOrFeatures.onRequest === 'function') {
    msgConnection = inputOrFeatures;
  } else if (
    inputOrFeatures &&
    typeof inputOrFeatures.on === 'function' &&
    output &&
    typeof output.write === 'function'
  ) {
    msgConnection = createMessageConnection(
      new StreamMessageReader(inputOrFeatures),
      new StreamMessageWriter(output),
    );
  } else {
    msgConnection = createMessageConnection(
      new StreamMessageReader(process.stdin),
      new StreamMessageWriter(process.stdout),
    );
  }

  let initializeHandler;
  let initializedHandler;
  let shutdownHandler;
  let exitHandler;

  msgConnection.onRequest('initialize', async (params, token) => {
    if (initializeHandler) {
      return await initializeHandler(params, token);
    }
    return { capabilities: {} };
  });

  msgConnection.onNotification('initialized', async (params) => {
    if (initializedHandler) {
      await initializedHandler(params);
    }
  });

  msgConnection.onRequest('shutdown', async () => {
    if (shutdownHandler) {
      await shutdownHandler();
    }
    return null;
  });

  msgConnection.onNotification('exit', async () => {
    if (exitHandler) {
      await exitHandler();
    }
  });

  const consoleLogger = {
    log: (msg) => msgConnection.sendNotification('window/logMessage', { type: 4, message: String(msg) }).catch(() => {}),
    info: (msg) => msgConnection.sendNotification('window/logMessage', { type: 3, message: String(msg) }).catch(() => {}),
    warn: (msg) => msgConnection.sendNotification('window/logMessage', { type: 2, message: String(msg) }).catch(() => {}),
    error: (msg) => msgConnection.sendNotification('window/logMessage', { type: 1, message: String(msg) }).catch(() => {}),
  };

  return {
    console: consoleLogger,
    listen: () => msgConnection.listen(),
    dispose: () => msgConnection.dispose(),
    onInitialize: (h) => { initializeHandler = h; },
    onInitialized: (h) => { initializedHandler = h; },
    onShutdown: (h) => { shutdownHandler = h; },
    onExit: (h) => { exitHandler = h; },
    onDidOpenTextDocument: (h) => msgConnection.onNotification('textDocument/didOpen', h),
    onDidChangeTextDocument: (h) => msgConnection.onNotification('textDocument/didChange', h),
    onDidSaveTextDocument: (h) => msgConnection.onNotification('textDocument/didSave', h),
    onDidCloseTextDocument: (h) => msgConnection.onNotification('textDocument/didClose', h),
    onDidChangeConfiguration: (h) => msgConnection.onNotification('workspace/didChangeConfiguration', h),
    onDidChangeWatchedFiles: (h) => msgConnection.onNotification('workspace/didChangeWatchedFiles', h),
    onDefinition: (h) => msgConnection.onRequest('textDocument/definition', h),
    onCompletion: (h) => msgConnection.onRequest('textDocument/completion', h),
    onCompletionResolve: (h) => msgConnection.onRequest('completionItem/resolve', h),
    onHover: (h) => msgConnection.onRequest('textDocument/hover', h),
    onDocumentSymbol: (h) => msgConnection.onRequest('textDocument/documentSymbol', h),
    onSignatureHelp: (h) => msgConnection.onRequest('textDocument/signatureHelp', h),
    onRequest: (method, h) => msgConnection.onRequest(method, h),
    onNotification: (method, h) => msgConnection.onNotification(method, h),
    sendRequest: (method, params) => msgConnection.sendRequest(method, params),
    sendNotification: (method, params) => msgConnection.sendNotification(method, params),
    sendDiagnostics: (params) => msgConnection.sendNotification('textDocument/publishDiagnostics', params),
  };
}

export default {
  TextDocumentSyncKind,
  CompletionItemKind,
  DiagnosticSeverity,
  MarkupKind,
  InsertTextFormat,
  SymbolKind,
  FileChangeType,
  ProposedFeatures,
  TextDocument,
  TextDocuments,
  createConnection,
};
